import { clamp01 } from '../core/contracts.js';
export function scoreTravelWindow(row={},policy={}){if(row.officialRestriction||row.criticalHazard||row.closed)return{eligible:false,score:null,reason:'HARD_GATE'};if(!Number.isFinite(row.weatherSuitability)||!Number.isFinite(row.demandSuitability))return{eligible:false,score:null,reason:'MISSING_REQUIRED_SIGNAL'};const daylight=Number.isFinite(row.daylightSuitability)?clamp01(row.daylightSuitability):.5;const mobility=Number.isFinite(row.mobilitySuitability)?clamp01(row.mobilitySuitability):.5;const score=.45*clamp01(row.weatherSuitability)+.35*clamp01(row.demandSuitability)+.1*daylight+.1*mobility;return{eligible:true,score:Math.round(score*1000)/1000};}
export function bestTravelWindows(rows=[],policy={}){return rows.map(row=>({row,result:scoreTravelWindow(row,policy)})).filter(x=>x.result.eligible).sort((a,b)=>b.result.score-a.result.score).slice(0,policy.limit||5);}
